import { db } from "./firebase";
import { collection, getDocs } from "firebase/firestore";

export async function fetchHalfYearlyAverages() {
  console.log("Fetching data from Firestore...");

  const querySnapshot = await getDocs(collection(db, "carbonEmissions"));
  let monthlyData = Array(12).fill(0);
  let counts = Array(12).fill(0);

  console.log("Query Snapshot Size:", querySnapshot.size);

  querySnapshot.forEach((doc) => {
    console.log("Document Data:", doc.data());

    const data = doc.data();
    if (!data.timestamp || !data.value) {
      console.error("Invalid document format:", doc.id, data);
      return;
    }

    const month = new Date(data.timestamp).getMonth(); // Get month (0 = Jan, 11 = Dec)
    monthlyData[month] += data.value;
    counts[month] += 1;
  });

  console.log("Monthly Data Before Averaging:", monthlyData);
  console.log("Counts:", counts);

  let averages = monthlyData.map((sum, index) =>
    counts[index] > 0 ? sum / counts[index] : 0
  );

  console.log("Averages:", averages);

  return {
    h1: { labels: ["Jan", "Feb", "Mar", "Apr", "May", "Jun"], data: averages.slice(0, 6) },
    h2: { labels: ["Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], data: averages.slice(6, 12) },
  };
}
